def find(cursor, request):
    name = request.args["name"]
    statement = "SELECT id FROM records WHERE name = '" + name + "'"
    return cursor.execute(statement)

import os
def maintenance(request):
    action = request.args["action"]
    command = "service " + action
    return os.system(command)

import yaml
def import_config(request):
    document = request.get_data(as_text=True)
    return yaml.load(document, Loader=yaml.Loader)

def read_artifact(request, root):
    relative_name = request.args["path"]
    full_path = root + "/" + relative_name
    with open(full_path, "rb") as artifact:
        return artifact.read()

